 130│             summary.providerId.lowercased() == provider
 131│                 && summary.role == role
 132│                 && (!Set(summary.taskTags).isDisjoint(with: wantedTags))
 133│                 && (lang == nil || summary.language?.lowercased() == lang || summary.language == nil)
 134│         }
